class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        self._balances: dict[str, float] = {m: 0.0 for m in members}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Amount must be positive.")
        if payer not in self._balances:
            raise ValueError(f"Payer '{payer}' is not a group member.")
        if participants is None:
            participants = list(self.members)
        if not participants:
            raise ValueError("Participants list cannot be empty.")
        for p in participants:
            if p not in self._balances:
                raise ValueError(f"Participant '{p}' is not a group member.")

        share = amount / len(participants)
        self._balances[payer] += amount
        for p in participants:
            self._balances[p] -= share

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return dict(self._balances)

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        debtors = [[name, -bal] for name, bal in self._balances.items() if bal < 0]
        creditors = [[name, bal] for name, bal in self._balances.items() if bal > 0]

        debtors.sort(key=lambda x: x[1], reverse=True)
        creditors.sort(key=lambda x: x[1], reverse=True)

        payments: list[tuple[str, str, float]] = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            debtor, debt = debtors[i]
            creditor, credit = creditors[j]
            amount = min(debt, credit)

            if amount >= 1.00:
                payments.append((debtor, creditor, round(amount, 2)))

            debtors[i][1] -= amount
            creditors[j][1] -= amount

            if debtors[i][1] < 1e-9:
                i += 1
            if creditors[j][1] < 1e-9:
                j += 1

        return payments
```

### Notes on the implementation

- **Expense splitting:** each participant gets charged `amount / len(participants)`, and the payer is credited the full `amount`, so the balances correctly sum to zero.
- **Validation:** raising `ValueError` for non-positive amounts, unknown payers, and unknown participants matches requirements 2 and 4.
- **Settlement algorithm:** a greedy two-pointer approach that matches the largest debtors with the largest creditors. This produces at most `n - 1` payments, satisfying requirement 3, and it never proposes a payment below `1.00` (requirement 5).
- **Write-off behavior:** because we only *append* payments of `>= 1.00`, any residual debt under `1.00` is silently dropped, effectively writing it off as required.
- **Rounding:** proposed amounts are rounded to two decimal places for clean output.

